import { test, expect } from '@playwright/test';

test.describe('Accessible Product Images and Login Fields', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should display accessible product images and login fields', async ({ page }) => {
    // Verify login fields have placeholder attributes
    const usernameField = page.getByLabel('Username');
    const passwordField = page.getByLabel('Password');
    await expect(usernameField).toHaveAttribute('placeholder', 'Enter your username');
    await expect(passwordField).toHaveAttribute('placeholder', 'Enter your password');

    // Verify login button is accessible
    const loginButton = page.getByRole('button', { name: 'Login' });
    await expect(loginButton).toBeVisible();

    // Login with standard user credentials
    await usernameField.fill('standard_user');
    await passwordField.fill('secret_sauce');
    await loginButton.click();

    // Wait for inventory page to load
    await page.waitForURL('https://www.saucedemo.com/inventory.');

    // Verify product images have alt attributes
    const productImages = page.locator('[data-testid="inventory-item-img"]');
    const imageCount = await productImages.count();
    expect(imageCount).toBeGreaterThan(0);

    for (let i = 0; i < imageCount; i++) {
      const img = productImages.nth(i);
      const altText = await img.getAttribute('alt');
      expect(altText).not.toBeNull();
      expect(altText).not.toBe('');
    }
  });

  test('should handle login with invalid credentials and still display accessible fields', async ({ page }) => {
    // Verify login fields have placeholder attributes
    const usernameField = page.getByLabel('Username');
    const passwordField = page.getByLabel('Password');
    await expect(usernameField).toHaveAttribute('placeholder', 'Enter your username');
    await expect(passwordField).toHaveAttribute('placeholder', 'Enter your password');

    // Attempt login with invalid credentials
    await usernameField.fill('invaliduser');
    await passwordField.fill('wrongpassword');
    const loginButton = page.getByRole('button', { name: 'Login' });
    await loginButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText('Epic sadface: Username and password do not match');
    await expect(errorMessage).toBeVisible();

    // Verify login fields are still accessible and retain placeholder attributes
    await expect(usernameField).toHaveAttribute('placeholder', 'Enter your username');
    await expect(passwordField).toHaveAttribute('placeholder', 'Enter your password');

    // Verify product images still have alt attributes even on error
    const productImages = page.locator('[data-testid="inventory-item-img"]');
    const imageCount = await productImages.count();
    expect(imageCount).toBeGreaterThan(0);

    for (let i = 0; i < imageCount; i++) {
      const img = productImages.nth(i);
      const altText = await img.getAttribute('alt');
      expect(altText).not.toBeNull();
      expect(altText).not.toBe('');
    }
  });
});
